<?php
 namespace Pterodactyl\Jobs\Dezerx; use Pterodactyl\Jobs\Job; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Illuminate\Queue\SerializesModels; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Contracts\Queue\ShouldQueue; use Pterodactyl\Services\Dezerx\FiveM\ServerConfig; use Pterodactyl\Services\Dezerx\Minecraft\ServerFiles; class InstallArtifact extends Job implements ShouldQueue { use Dispatchable; use InteractsWithQueue; use SerializesModels; public int $timeout = 1800; public int $tries = 1; private const ARCHIVE = 'fx.tar.xz'; private const RUNTIME = ['alpine', 'run.sh']; public function __construct( public Server $server, public string $build, public string $url, ) { } public function handle(): void { $files = new ServerFiles($this->server); $this->stopServer($files); if (!$files->pullFile('/', $this->url, self::ARCHIVE)) { Log::warning('FiveM artifact pull refused by node', $this->context()); return; } if (!$this->awaitFile($files)) { Log::warning('FiveM artifact never arrived on node', $this->context()); return; } $files->deletePaths('/', $this->presentRuntime($files)); if (!$files->decompress('/', self::ARCHIVE)) { Log::warning('FiveM artifact downloaded but could not be unpacked', $this->context()); return; } $files->deletePaths('/', [self::ARCHIVE]); \Pterodactyl\Services\Dezerx\Brand::write($files, '/', ServerConfig::MARKER_SUFFIX, $this->build . "\n"); } private function presentRuntime(ServerFiles $files): array { $names = []; foreach ($files->listFiles('/') ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (in_array($name, self::RUNTIME, true)) { $names[] = $name; } } return $names; } private function stopServer(ServerFiles $files, int $seconds = 60): void { if ($files->powerState() === 'offline') { return; } $files->setPower('kill'); $deadline = microtime(true) + $seconds; do { sleep(3); if ($files->powerState() === 'offline') { return; } } while (microtime(true) < $deadline); Log::warning('Server would not stop before artifact install', $this->context()); } private function awaitFile(ServerFiles $files, int $minutes = 20): bool { $deadline = microtime(true) + ($minutes * 60); $previous = null; do { sleep(5); $size = $files->entrySize('/', self::ARCHIVE); if ($size !== null && $size > 0 && $size === $previous) { return true; } $previous = $size; } while (microtime(true) < $deadline); return false; } private function context(): array { return ['server' => $this->server->uuid, 'build' => $this->build]; } } 